interface Feedback {
  id: string;
  interviewId: string;
  totalScore: number;
  categoryScores: Array<{
    name: string;
    score: number;
    comment: string;
  }>;
  strengths: string[];
  areasForImprovement: string[];
  finalAssessment: string;
  createdAt: string;
}

interface Interview {
  id: string;
  role: string;
  level: InterviewLevel;
  questions: string[];
  techstack: string[];
  createdAt: string;
  userId: string;
  type: InterviewType;
  finalized: boolean;
}

interface CreateFeedbackParams {
  interviewId: string;
  userId: string;
  transcript: { role: string; content: string }[];
  feedbackId?: string;
}

interface User {
  name: string;
  email: string;
  id: string;
}

interface InterviewCardProps {
  id: string;
  userId: string;
  role: string;
  type: InterviewType;
  techstack: string[];
  level: InterviewLevel;
  questions: string[];
  finalized: boolean;
  createdAt: string;
}

interface AgentProps {
  userName: string;
  userId?: string;
  interviewId?: string;
  feedbackId?: string;
  type: "generate" | "interview";
  questions?: string[];
}

interface RouteParams {
  params: Promise<Record<string, string>>;
  searchParams: Promise<Record<string, string>>;
}

interface GetFeedbackByInterviewIdParams {
  interviewId: string;
  userId: string;
}

interface GetLatestInterviewsParams {
  userId: string;
  limit?: number;
}

interface SignInParams {
  email: string;
  idToken: string;
}

interface SignUpParams {
  uid: string;
  name: string;
  email: string;
  password: string;
}

type FormType = "sign-in" | "sign-up";

interface InterviewFormProps {
  interviewId: string;
  role: string;
  level: string;
  type: string;
  techstack: string[];
  amount: number;
}

interface TechIconProps {
  techstack: string[];
}

enum InterviewType {
  "Technical" = "Technical",
  "HR" = "HR",
  "Mixed" = "Mixed",
}

enum InterviewLevel {
  "Internship" = "Internship",
  "Junior" = "Junior",
  "Mid" = "Mid",
  "Senior" = "Senior",
  "Lead" = "Lead",
}
